H=[['拉丁 claudere；分词 clausus','关上、围住、使结束；复合词常变为 -cludere / -clusus']]
INC=H+[['拉丁 in- + claudere → inclūdere → 中古英语 includen','关在里面、纳入'],['英语 include','把某人或某物算在范围内']]
EXC=H+[['拉丁 ex- + claudere → exclūdere → 英语 exclude','关在外面 → 排除、不让进入']]
EXV=H+[['拉丁 exclūdere → 中世纪拉丁 exclūsīvus → 英语 exclusive','排除 → 限于特定对象、独有的']]
CON=H+[['拉丁 con- + claudere → conclūdere → 中古英语 concluden','合拢、封住 → 结束、作出最终判断'],['英语 conclude','结束；推断、得出结论；达成协议']]
REC=H+[['晚期拉丁 reclūdere / reclūsus → 古法语 reclus','闭居、隔绝；古典拉丁同词也曾表示打开'],['中古英语 reclus → 英语 recluse','隐居者 → 很少与外界来往的人']]
PH=H+[['拉丁 claustrum + 希腊来源后缀 -phobia → 英语 claustrophobia','封闭场所 + 恐惧 → 对幽闭空间的强烈恐惧']]
SEC=H+[['拉丁 sē-“分开” + claudere → sēclūdere → 中古英语 secluden','隔开、关在一旁'],['英语 seclude','使远离外界；隐居、独处']]
CL=H+[['拉丁 clausus → 古法语 clos → 中古英语 clos / closen','关闭的、封闭处；关上'],['并行合流：古英语 clȳsan / beclȳsan → 中古英语动词','关上、围住，与法语路线汇合'],['现代英语 close','关上、结束；距离小、亲密；另有封闭小院或尽头巷道等名词义']]
ENC=H+[['拉丁 inclūdere → 古法语 enclore / enclos → 中古英语 enclosen','围在里面、包入'],['现代英语 enclose','围住；随信附上']]
DIS=H+[['通俗拉丁 *disclaudere → 古法语 desclore / desclos → 中古英语 disclosen','解除封闭、打开；星号形式是重建'],['现代英语 disclose','把原先没有公开的信息说出来']]
CV=H+[['拉丁 conclūdere → 晚期拉丁 conclūsīvus → 法语 conclusif → 英语 conclusive','结束、论定 → 能作出确定结论的']]
W=[
E('include','/ɪnˈkluːd/','包括；把……纳入','先画一个范围，再把这个成员算在里面。','拉丁 in-“在内” + claudere“关、围”，形成 inclūdere，借入中古英语。',INC,'The price includes breakfast 是早餐已经算在价格里。include A 通常只说明 A 在内，不保证后面列出的东西就是全部。','include something in；be included in；include the cost of。','contain 常说容器实际装着什么；include 常说分类、名单、套餐等把什么算入。',('The ticket price includes a guided tour.','票价包括一次导览。'),('Please include your phone number in the message.','请在留言中写上你的电话号码。')),
E('exclusive','/ɪkˈskluːsɪv/','独有的；专用的；排他的；高档且限制进入的；独家报道','门只给某些人或某一方打开，其他人被挡在外面。','来自拉丁 exclūdere 的形容词派生 exclūsīvus；现代可联系 exclude，但不是简单把英语词尾换掉就解释全部历史。',EXV,'exclusive rights 是独家权利；exclusive to members 是会员专享；an exclusive 可以是独家新闻。exclusive of tax 则是税未算进去，不能误读为“税款独享”。','exclusive access；exclusive to；mutually exclusive；exclusive of。','expensive 只是贵；exclusive 还强调限制对象、排他或独有。mutually exclusive 指不能同时成立。',('This area is for the exclusive use of residents.','这个区域仅供住户使用。'),('The newspaper published an exclusive interview with the explorer.','报纸刊登了对这位探险家的独家采访。'),('The quoted price is exclusive of tax.','报价不含税。'),sources=['https://www.etymonline.com/word/exclusive','https://en.wiktionary.org/wiki/exclusive#English']),
E('exclusively','/ɪkˈskluːsɪvli/','仅仅；专门；独家地','范围就到这里，其他对象或渠道不算在内。','中古英语已有对应形式；结构上是 exclusive + -ly。',EXV[:1]+[['拉丁 exclūsīvus → 中古英语 exclusive / exclusyvely','排他的 → 仅限某对象地'],['现代英语 exclusively','只、专门、独家地']],'sold exclusively online 是只在线上销售；work exclusively on one project 是全部精力只用于一个项目。重点在限制范围，不是笼统地强调做得很专业。','exclusively for；exclusively on；available exclusively through。','especially 是尤其，可以还有其他对象；exclusively 是只限指定范围。',('The course is designed exclusively for beginners.','这门课程专为初学者设计。'),('The album was released exclusively through the artist’s website.','这张专辑只通过艺术家的网站发行。')),
E('clause','/klɔːz/','分句、小句；条款；子句〔计算机〕','把一段话看成内部有结构、能够单独辨认的一块。','拉丁 clausus 的名词形式 clausa 在中世纪拉丁表示结束、语句单元，经古法语 clause 进入英语；不是 close 的现代拼写变体。',H+[['中世纪拉丁 clausa → 古法语 clause → 中古英语 clause','语句的收束、独立的一段 → 分句、条款']],'语法里 She left 是一个 clause；because she was tired 也是，只是依赖主句。合同里的 clause 是一条单独规定。一般以动词及其相关成分组织，不要死记成每次都必须出现明写的主语。','a main clause；a subordinate clause；a clause in a contract。','sentence 是完整句子，可含多个 clauses；phrase 是短语，通常不是这样围绕一个述谓关系组织的分句。',('The sentence “I left because it was late” contains two clauses.','I left because it was late 这个句子包含两个分句。'),('They added a clause explaining how the equipment should be returned.','他们加了一条说明设备应如何归还的条款。'),sources=['https://www.etymonline.com/word/clause','https://en.wiktionary.org/wiki/clause#English']),
E('conclude','/kənˈkluːd/','结束；得出结论；达成〔协议〕','把散开的事情收束起来：谈话收尾，推理落到判断，谈判落到结果。','拉丁 con-“一起、加强” + claudere，形成 conclūdere，借入英语。',CON,'conclude a speech 是结束演讲；conclude that... 是判断某事成立；conclude an agreement 是达成协议。三种对象不同，不必一律翻成“总结”。','conclude with；conclude that；conclude from；conclude an agreement。','summarize 是概括要点；conclude 可以结束，也可作判断，不要求把前文重述一遍。',('She concluded her talk with a short demonstration.','她用一段简短演示结束了讲话。'),('From the marks on the floor, we concluded that the table had been moved.','根据地板上的痕迹，我们判断桌子被移动过。'),sources=['https://www.etymonline.com/word/conclude','https://en.wiktionary.org/wiki/conclude#English']),
E('exclude','/ɪkˈskluːd/','排除；不包括；不让参加','把某人或某个可能性留在所定范围之外。','拉丁 ex-“向外” + claudere，形成 exclūdere，再借入英语。',EXC,'exclude someone from a meeting 是不让某人参会；exclude tax 是不把税算进去；exclude a possibility 是排除一种可能。对象既可以是人，也可以是费用或解释。','exclude somebody from；exclude the possibility of；exclude taxes。','include 算在内，exclude 留在外；ignore 是不理会，未必正式从范围中剔除。',('The quoted fee excludes travel expenses.','报价不包括差旅费。'),('The evidence does not exclude the possibility of an error.','这些证据并未排除出错的可能。')),
E('exclusivity','/ˌekskluːˈsɪvəti/','独家性；专属性；排他性','这种资格、内容或关系只属于有限的一方或几方。','exclusive + -ity；重音移到后面的 -siv- 一带。',EXV+[['英语 exclusive + -ity → exclusivity','独有、限量开放或排他的性质']],'一个品牌可营造 exclusivity，让人感觉不是谁都能买到；发行合同可约定 exclusivity，只交给一个平台。它不总是正面，高门槛也可能把人排斥在外。','an exclusivity agreement；a sense of exclusivity；a period of exclusivity。','scarcity 是稀少；exclusivity 强调获取或使用被限定，限量只是实现方式之一。',('The publisher asked for six months of exclusivity.','出版方要求六个月的独家权。'),('The club’s appeal depends partly on its sense of exclusivity.','这家俱乐部的吸引力部分来自它给人的专属感。')),
E('recluse','英 /rɪˈkluːs/；美 /ˈrekluːs/','隐居者；很少与人来往的人','像把自己与外界隔开，生活中很少出现社交接触。','经古法语 reclus，接晚期拉丁 reclūsus“闭居的”；它的动词 reclūdere 在古典拉丁也有“打开”义，不能把 re- 永远机械理解成再关一次。',REC,'早期常指宗教隐修者，现代也可指远离社交生活的人。仅仅喜欢独处一会儿，并不自动就是 a recluse。','live as a recluse；become a recluse；a virtual recluse。','introvert 是偏好较少刺激或内向的人；recluse 描述明显远离社会往来的生活方式。',('The novelist lived as a recluse in a remote farmhouse.','这位小说家隐居在偏僻的农舍里。'),('After retirement, he became a virtual recluse and rarely received visitors.','退休后他几乎过起隐居生活，很少接待来客。'),sources=['https://www.etymonline.com/word/recluse','https://www.oxfordlearnersdictionaries.com/definition/english/recluse']),
E('claustrophobic','英 /ˌklɒstrəˈfəʊbɪk/；美 /ˌklɔːstrəˈfoʊbɪk/','怕幽闭空间的；狭窄得令人压抑的','人觉得被困住，或者空间给人这种被困住的感觉。','claustrophobia 的词族换成 -ic 形容词；claustr- 来自拉丁 claustrum“封闭场所”。',PH+[['英语 claustrophobia → claustrophobic','有幽闭恐惧的；使人感到狭窄压抑的']],'I feel claustrophobic 说人的感受；a claustrophobic room 说房间引发的感觉。日常形容压抑空间，不等于对某个人作临床诊断。','feel claustrophobic；a claustrophobic room；a claustrophobic atmosphere。','cramped 说空间局促；claustrophobic 进一步强调局促带来的被困、压抑感。',('The low ceiling made the tiny room feel claustrophobic.','低矮的天花板让小房间显得压抑憋闷。'),('She felt claustrophobic in the crowded lift.','她在拥挤的电梯里感到被困住般的压抑。'),sources=['https://www.merriam-webster.com/dictionary/claustrophobic','https://en.wiktionary.org/wiki/claustrophobic#English']),
E('reclusive','/rɪˈkluːsɪv/','隐居的；不爱与外界来往的','生活方式朝独处那边靠，很少出现在公众场合。','recluse + -ive，从隐居者或隐居状态形成形容词。',REC+[['英语 recluse + -ive → reclusive','倾向隐居、避开社交的']],'a reclusive artist 可以只是长期回避公众，并不说明没有亲友。它描写可观察到的生活方式，不必推断对方是否孤独、是否快乐。','a reclusive writer；a reclusive lifestyle；increasingly reclusive。','private 只是重视隐私；reclusive 的社交退避程度通常更明显。',('The reclusive painter rarely gave interviews.','这位深居简出的画家很少接受采访。'),('She chose a quiet, reclusive life in the mountains.','她选择在山中过安静的隐居生活。')),
E('occlusion','/əˈkluːʒən/','堵塞；遮挡；牙齿咬合','一个通路被封住，或两个表面闭合到一起。','借晚期拉丁 occlūsiō，接拉丁 occlūdere“堵住”，其中 ob- 在 c 前同化为 oc-。',H+[['拉丁 ob- + claudere → occlūdere → 晚期拉丁 occlūsiō','挡在前面并关闭 → 堵塞、闭合'],['英语 occlusion','阻塞、遮挡；牙齿咬合等技术义']],'血管的 occlusion 是通路受阻；图像里的 occlusion 是前面的物体挡住后面物体；牙科说上下牙接触时的咬合关系，并非“牙齿堵塞”。','occlusion of a vessel；visual occlusion；dental occlusion。','obstruction 常说阻碍物或阻塞；occlusion 在技术语境里还可指正常闭合接触，如牙齿咬合。',('The dentist checked how the teeth met during occlusion.','牙医检查了上下牙咬合时的接触情况。'),('The tracking system lost the ball because of partial occlusion by a player.','球被一名球员部分挡住，追踪系统因此丢失了目标。'),sources=['https://www.merriam-webster.com/dictionary/occlusion','https://en.wiktionary.org/wiki/occlusion#English']),
E('claustrophobia','英 /ˌklɒstrəˈfəʊbiə/；美 /ˌklɔːstrəˈfoʊbiə/','幽闭恐惧症；对封闭狭小空间的强烈恐惧','怕的重点是被关在里面、难以离开，不只是房间尺寸小。','近代术语，用拉丁 claustrum“封闭场所”配希腊来源的 -phobia“恐惧”；不是古罗马已有的完整英语词。',PH,'电梯、小舱室等可能出现在这种恐惧的描述中。它比一般“不喜欢小房间”更强；这里学习的是词义，不靠一个例句给人贴诊断标签。','experience claustrophobia；a history of claustrophobia；feelings of claustrophobia。','claustr- 说封闭；phobia 说强烈恐惧。claustrophobia 与单纯怕黑不是同一个概念。',('He described his claustrophobia as a fear of being unable to get out.','他把自己的幽闭恐惧描述为害怕无法离开。'),('The character’s claustrophobia becomes clear during the submarine scene.','在潜艇那场戏里，角色的幽闭恐惧表现得很明显。'),sources=['https://www.etymonline.com/word/claustrophobia','https://en.wiktionary.org/wiki/claustrophobia#English']),
E('seclude','/sɪˈkluːd/','使隔绝；使独处；隐居','在自己与外面的来往之间拉开一道界线。','拉丁 sē-“分开” + claudere，形成 sēclūdere，借入英语。',SEC,'常见 seclude oneself：自己退到安静地方，不与人往来。也能说树木等把一个地点与外界隔开；动词本身较书面。','seclude oneself；seclude somebody from；seclude a garden。','exclude 强调不让进入某个范围；seclude 强调把人或地方安置在与外界隔开的状态。',('She secluded herself in the cabin to finish the manuscript.','她独自住进小屋，专心完成手稿。'),('Tall hedges seclude the garden from the busy road.','高树篱把花园与繁忙道路隔开。'),sources=['https://www.etymonline.com/word/seclude','https://en.wiktionary.org/wiki/seclude#English']),
E('close','动词、结束名词：英 /kləʊz/ 美 /kloʊz/；形容词、副词及围地名词：英 /kləʊs/ 美 /kloʊs/','关上；结束；接近的；亲密的；结尾；小院、尽头巷道','关上缝隙，两边就靠近了；距离的小又能变成关系的亲密。','主要经法语 clos 接拉丁 clausus；动词又与古英语 clȳsan 等形式合流。现代 /z/ 与 /s/ 的读法要按词性和词义分。',CL,'close the door 的尾音是 /z/；a close friend 的尾音是 /s/。bring something to a close 的“结束”读 /z/；街名里的 Close 或教堂围地名词常读 /s/，不能只背“名词都读一种”。','close a shop；close to；a close friend；a close contest；come to a close。','closed 是关着的；close 作形容词通常是近的、亲密的。The shop is close 与 The shop is closed 意义不同。',('Please close the window before you leave.','离开前请关上窗户。'),('The station is close to our hotel.','车站离我们的酒店很近。'),('The concert came to a close just before ten.','音乐会在十点前结束了。'),sources=['https://www.etymonline.com/word/close','https://en.wiktionary.org/wiki/close#English']),
E('closed','英 /kləʊzd/；美 /kloʊzd/','关闭的；不开放的；已结束的；封闭的','开口、参与通道或讨论空间已经合上。','close 的过去式、过去分词兼形容词；尾部读 /zd/，不多读一个完整音节。',CL[:2]+[['中古英语 close / closed → 现代英语 closed','关上 → 关着的、不开放的']],'a closed shop 可以表示店已关门，但作为劳动关系术语还可指只雇用工会会员的工作场所，须看语境。closed meeting 是不对公众开放的会议，不是已经散会。','closed for repairs；closed to the public；a closed meeting；a closed case。','close /kləʊs/ 是近的；closed /kləʊzd/ 是关着的，词尾变化带来真正的意义区别。',('The gallery is closed for repairs this week.','画廊这周因维修关闭。'),('The committee discussed the matter in a closed meeting.','委员会在不公开的会议上讨论了此事。')),
E('closure','英 /ˈkləʊʒə/；美 /ˈkloʊʒər/','关闭；结束；心理上的了结；封口装置；闭包〔计算机〕','把原来敞开的过程收束，或把一组相关东西包在一个边界内。','晚期拉丁 clausūra 经古法语 closure 借入中古英语；现代可联系 close，但名词本身有独立借入史。',H+[['晚期拉丁 clausūra → 古法语 closure → 中古英语 closure','封闭、围合、关闭'],['英语后续引申','设施关闭、事情了结；数学或程序中的闭包']],'road closure 是封路；emotional closure 是对一段经历有了相对完整的结束感。程序里的 closure 则把函数与其能访问的词法环境联系在一起，不是“关闭程序”。','road closure；factory closure；a sense of closure；a function closure。','closing 常突出正在关闭或最后阶段；closure 可指关闭的事件、结果或收束感。程序 closure 是专门概念，要另看语境。',('The road closure added twenty minutes to our journey.','封路让我们的行程多花了二十分钟。'),('Finishing the letter gave her a sense of closure.','写完这封信让她有了一种事情终于告一段落的感觉。'),('The returned function forms a closure that keeps access to the counter.','返回的函数形成一个闭包，仍能访问那个计数变量。'),sources=['https://www.etymonline.com/word/closure','https://developer.mozilla.org/en-US/docs/Web/JavaScript/Guide/Closures','https://en.wiktionary.org/wiki/closure#English']),
E('disclose','英 /dɪsˈkləʊz/；美 /dɪsˈkloʊz/','透露；披露；揭示','把原来像关在里面的信息打开，让别人知道。','经古法语 desclore / desclos，远接拉丁 claudere；通俗拉丁 *disclaudere 是重建形式。现代可按 dis- + close 理解。',DIS,'disclose information 是把信息公开或告诉有关的人；不一定是泄密，也可以是按要求正式披露。说 disclose something to someone，通常不说 disclose someone something。','disclose details；disclose that；disclose information to；decline to disclose。','discover 是发现原本不知道的事；disclose 是把信息告知别人，二者行动方向不同。',('The company declined to disclose the purchase price.','公司拒绝透露收购价格。'),('She disclosed the problem to the project manager.','她把这个问题告知了项目经理。'),sources=['https://www.etymonline.com/word/disclose','https://en.wiktionary.org/wiki/disclose#English']),
E('disclosure','英 /dɪsˈkləʊʒə/；美 /dɪsˈkloʊʒər/','披露；透露的信息','把原来没有说出的事拿出来，或指这次拿出来的内容。','英语 disclose 参照 closure 的形式构成 disclosure，不必另造一个拉丁借词祖先。',DIS+[['英语 disclose，参照 closure → disclosure','公开、透露的行为或内容']],'full disclosure 是充分披露；a surprising disclosure 是令人意外的透露。商业、研究等场合常谈 disclosure，但这个词本身不说明某项具体法律义务。','disclosure of；full disclosure；financial disclosure；voluntary disclosure。','exposure 常强调暴露甚至揭丑；disclosure 也可中性地指按流程提供信息。',('The report includes a disclosure of the study’s funding sources.','报告披露了研究的经费来源。'),('The unexpected disclosure changed the direction of the discussion.','这条出人意料的消息改变了讨论方向。')),
E('enclosure','英 /ɪnˈkləʊʒə/；美 /ɪnˈkloʊʒər/','围起的区域；围栏、外壳；围合；随信附件','外面围一圈，里面留出一块地方；附在信里的东西也被包在里面。','古法语 enclosure 经中古英语借入，接 enclore 和拉丁 inclūdere；与 inclusion 同源，但走了不同借入路线。',H+[['拉丁 inclūdere → 古法语 enclore / enclosure → 中古英语 enclosure','围住 → 围合的地方或过程'],['现代英语 enclosure','围栏区域、保护壳；信封内的附件']],'an animal enclosure 是动物围栏区；an electrical enclosure 是设备外壳。信末的 enclosure 提醒收件人里面还有附带材料；不专指电子邮件附件。','an animal enclosure；a protective enclosure；the enclosed documents；enclosure of land。','fence 是围栏本身；enclosure 常是围出的区域或完整外壳，也可指围合的过程。',('The birds have a large outdoor enclosure.','这些鸟有一片宽敞的户外围栏区。'),('The letter listed two enclosures: a map and an application form.','信中列了两份附件：一张地图和一份申请表。')),
E('enclose','英 /ɪnˈkləʊz/；美 /ɪnˈkloʊz/','围住；把……装入；随信附上','让某样东西待在边界或容器里面。','古法语 enclore / enclos 经中古英语形成 enclose，远接拉丁 inclūdere。现代 en- + close 的拆法是辅助理解，不代表所有变化都发生在英语里。',ENC,'enclose a garden with a wall 是用墙围住花园；enclose a form 是把表格随信放进去。现代邮件里也有人沿用它，但电子附件通常说 attach 更直接。','enclose something in；enclose something with；please find enclosed。','include 是把某物算作一部分；enclose 更有围住、装进或随信放入的空间感。',('A stone wall encloses the garden.','一堵石墙围着花园。'),('I have enclosed a copy of the receipt with this letter.','我随信附上了收据复印件。'),sources=['https://www.etymonline.com/word/enclose','https://en.wiktionary.org/wiki/enclose#English']),
E('inclusion','/ɪnˈkluːʒən/','纳入；包含；包容；内含物','让某个成员进入范围，或者看见材料里包着的东西。','借拉丁 inclūsiō，接 inclūdere“围在里面”；现代对应 include，但名词也有独立借入路线。',H+[['拉丁 inclūdere → inclūsiō → 英语 inclusion','围在里面 → 纳入、包含'],['英语社会与材料用法','让成员参与；材料内部的包裹物']],'社会语境的 inclusion 不只是在名单上写一个名字，还常关注能否实际参与。宝石里的 an inclusion 则是晶体形成时包住的其他物质，不是社会概念。','inclusion in；the inclusion of；social inclusion；a mineral inclusion。','diversity 说成员有哪些不同；inclusion 说这些成员能否进入并参与，两者相关但不是同一个问题。',('The committee approved the inclusion of a practical workshop.','委员会批准把一个实操工作坊纳入活动。'),('A tiny mineral inclusion is visible inside the crystal.','晶体内部可以看到一粒微小的矿物包裹体。')),
E('inclusive','/ɪnˈkluːsɪv/','包括在内的；兼容包容的；首尾都计入的','边界以内的人、费用或端点，都给它留一个位置。','中世纪拉丁 inclūsīvus，经中古法语 inclusif 借入英语；接拉丁 inclūsus“围在里面的”。',H+[['拉丁 inclūdere / inclūsus → 中世纪拉丁 inclūsīvus → 法语 inclusif','围入 → 包含在内的'],['英语 inclusive','包含相关项目、端点或不同群体的']],'Monday to Friday inclusive 包括周一和周五。inclusive of tax 是含税；an inclusive workplace 强调让不同背景的人能参与和被接纳。','inclusive of；from...to...inclusive；an inclusive environment。','exclusive of tax 是不含税；inclusive of tax 是含税。exclusive club 限制进入，inclusive group 力求接纳。',('The price is inclusive of delivery.','价格包含配送费。'),('The museum will be closed from Monday to Wednesday inclusive.','博物馆从周一到周三闭馆，周一和周三都包括在内。'),('The team is working to create a more inclusive environment.','团队正在努力营造一个更包容的环境。')),
E('exclusion','/ɪkˈskluːʒən/','排除；排斥；不包括的项目','把谁留在外面，或者明确哪些事项不算。','拉丁 exclūsiō 经法语及拉丁借入中古英语，接 exclūdere；现代可联系 exclude 理解。',H+[['拉丁 exclūdere → exclūsiō → 法语／中古英语 exclusion','关在外面 → 排除、不给参与'],['现代英语 exclusion','排斥的行为；合同、范围等不包含的项目']],'social exclusion 是被排除在社会参与之外；a policy exclusion 是保单不保的项目，具体范围由文本决定。to the exclusion of 表示只顾一个，其他都被挤开。','exclusion from；the exclusion of；to the exclusion of；an exclusion clause。','exception 是从一般规则中提出的例外；exclusion 是明确不纳入的对象或事项，二者不必重合。',('The study explains the exclusion of incomplete responses.','研究说明了为何排除不完整答卷。'),('He focused on one project to the exclusion of all others.','他只顾一个项目，把其他项目全搁下了。')),
E('conclusion','/kənˈkluːʒən/','结尾；结束；结论','把材料、推理或过程收在一个落点上。','古法语 conclusion 借自拉丁 conclūsiō，来自 conclūdere 的分词词干；英语不是只在 conclude 后现加一个尾巴。',H+[['拉丁 conclūdere → conclūsiō → 古法语 conclusion → 中古英语','结束、论定 → 结尾、结论'],['现代英语 conclusion','过程的收束；依据证据作出的判断']],'the conclusion of a film 是结尾；draw a conclusion 是作出推断。in conclusion 引出收尾的话；不能因为某句话放在最后，就当它一定有证据支持。','reach a conclusion；draw conclusions from；jump to conclusions；in conclusion。','result 是得到的结果；conclusion 常是人从结果、证据或论证中形成的判断。',('We cannot draw a firm conclusion from such a small sample.','样本这么小，我们无法作出可靠结论。'),('The conclusion of the novel brings the two stories together.','小说结尾把两条故事线合到了一起。')),
E('conclusive','/kənˈkluːsɪv/','确凿的；能定论的；决定性的','证据强到足以把争论收住，不再只是提示一种可能。','晚期拉丁 conclūsīvus，经法语 conclusif 借入；接 conclūdere“结束、论定”。',CV,'conclusive evidence 是足以支持确定判断的证据。它不是“摆在文章结尾的证据”，也不是单纯“看起来有点说服力”。','conclusive evidence；conclusive proof；a conclusive result。','convincing 是令人信服；conclusive 更强调足以定论、结束疑问。',('The photograph provided conclusive evidence that the bridge had already collapsed.','照片提供了桥梁当时已经坍塌的确凿证据。'),('The test was useful, but its result was not conclusive.','这个测试有用，但结果还不足以下定论。'),sources=['https://www.etymonline.com/word/conclusive','https://en.wiktionary.org/wiki/conclusive#English']),
E('inconclusive','/ˌɪnkənˈkluːsɪv/','不能定论的；无明确结果的','门还关不上：现有材料不能把答案钉牢。','否定 in- + conclusive；这里 in- 是“不”，不是 include 里的“在里面”。',CV+[['英语 in- + conclusive → inconclusive','不足以给出确定结论的']],'inconclusive results 不等于证明“没有效果”或“事情没发生”，只表示这些结果不能作明确判断。原因可能是材料少、结果矛盾等。','inconclusive evidence；inconclusive results；remain inconclusive。','negative result 是检测或判断没有发现某对象等特定结果；inconclusive 是无法判定，不能一律当作否定。',('The investigation remained inconclusive because key records were missing.','由于关键记录缺失，调查仍未能得出明确结论。'),('The two experiments produced inconclusive results.','两次实验都没有得到足以下定论的结果。')),
E('secluded','/sɪˈkluːdɪd/','僻静的；与外界隔开的','外面再热闹，这一小块地方也不容易被打扰。','seclude 的过去分词转为形容词，接拉丁 sēclūdere。',SEC+[['英语 seclude → secluded','被隔开 → 僻静、隐蔽的']],'a secluded beach 可能离主要道路远，也可能被地形挡住。它不自动表示荒无人烟，更不保证无人能发现。','a secluded spot；a secluded garden；a secluded beach。','remote 强调地理距离远；secluded 强调隔开、不受打扰，市区里也可以有 secluded courtyard。',('We found a secluded spot behind the old orchard.','我们在老果园后面找到一处僻静地方。'),('The hotel has a secluded courtyard away from the street.','酒店有一个与街道隔开的僻静庭院。')),
E('seclusion','/sɪˈkluːʒən/','独处；隐居；隔离状态','与外界的来往减少到很少，自己处在一块隔开的空间里。','借中世纪拉丁 sēclūsiō，来自拉丁 sēclūdere 的分词词干；现代与 seclude 对应。',H+[['拉丁 sēclūdere → 中世纪拉丁 sēclūsiō → 英语 seclusion','隔开 → 与外界分离的状态或行为']],'live in seclusion 是隐居；seek seclusion 是找个清静地方独处。它可以是主动选择，也可以由外部安排，须看上下文；并不自带“内心孤独”的评价。','in seclusion；seek seclusion；the seclusion of a garden。','solitude 侧重独自一人的状态或体验；seclusion 更突出与公众、外界隔开。',('The composer spent several months in seclusion working on the opera.','作曲家独处了几个月，专心创作这部歌剧。'),('Visitors come here for the quiet and seclusion.','游客来这里享受安静、远离打扰的环境。'),sources=['https://www.etymonline.com/word/seclusion','https://en.wiktionary.org/wiki/seclusion#English']),
E('occlude','/əˈkluːd/','堵住；遮住；咬合〔牙齿〕','把通路或视线挡上，或者让相对的表面合拢接触。','借拉丁 occlūdere：ob-“挡在前面”在 c 前变成 oc-，再接 claudere 的复合形式 -cludere。',H+[['拉丁 ob- + claudere → occlūdere → 英语 occlude','堵在前面、关闭 → 阻塞、遮挡、咬合']],'属于技术或正式词。渲染中的物体可以 occlude 背后的对象；牙科 teeth occlude 指上下牙接触咬合，不是说牙齿成了障碍物。','occlude a passage；occlude the view；teeth occlude。','occult“隐秘的”接拉丁 occulere“隐藏”，不是这里 claudere 的派生。长得像，不等于同一个来源。',('The foreground building occludes part of the tower in the image.','画面前景的建筑挡住了塔的一部分。'),('The model shows how the upper and lower teeth occlude.','模型展示了上下牙如何咬合。'),sources=['https://www.merriam-webster.com/dictionary/occlude','https://www.oxfordlearnersdictionaries.com/definition/english/occlude']),
E('preclude','/prɪˈkluːd/','使不可能；阻止；预先排除','先把某条路堵上，后面的动作就走不通了。','拉丁 prae-“在前” + claudere 形成 praeclūdere，借入英语。',H+[['拉丁 prae- + claudere → praeclūdere → 英语 preclude','预先封住 → 使某事无法发生或无法进行']],'preclude further discussion 是使继续讨论不可能；preclude someone from doing 是使某人无法做。它不要求有人故意设阻，时间或条件也可以成为原因。','preclude the possibility of；preclude somebody from doing；preclude further action。','prevent 更普通；preclude 较正式，常强调条件已经把某种选择排除了。',('The narrow entrance precludes the use of large vehicles.','入口太窄，无法使用大型车辆。'),('Her schedule precluded her from attending the afternoon session.','她的日程使她无法参加下午的会议。'),sources=['https://www.etymonline.com/word/preclude','https://en.wiktionary.org/wiki/preclude#English']),
E('closet','英 /ˈklɒzɪt/；美 /ˈklɑːzɪt/','壁橱；储物间；私下的、未公开的；使在密室独处','最初是一小块围起来的私密空间，后来常用来收纳物品。','古法语 clos“小围地、封闭空间”加小称后缀 -et，形成 closet；远接拉丁 clausum。',H+[['拉丁 clausum → 古法语 clos + -et → closet','封闭空间 → 小型私室'],['中古英语 closet → 现代英语 closet','私室 → 壁橱、储物间；再引申未公开的状态']],'a clothes closet 是衣橱；a closet fan 可以是没公开承认的爱好者。come out of the closet 常谈公开自己的性取向或性别身份，也有更广的公开隐瞒之事的用法。','a storage closet；a closet admirer；come out of the closet；be closeted with。','wardrobe 常专指放衣服的柜子或衣物整体；closet 可以是嵌入墙体的小储藏空间，装的也未必是衣服。',('The spare blankets are in the hallway closet.','备用毯子在走廊的壁橱里。'),('He turned out to be a closet fan of romantic comedies.','原来他私下里很喜欢浪漫喜剧。'),sources=['https://www.etymonline.com/word/closet','https://en.wiktionary.org/wiki/closet#English']),
E('cloister','英 /ˈklɔɪstə/；美 /ˈklɔɪstər/','回廊；修道院生活或院落；使与外界隔绝','围着庭院形成一个安静的内圈，修道生活便与外部世界隔开。','拉丁 claustrum“围合处、门闩”，在中世纪用于修道院封闭区域，经古法语 cloistre 借入英语。',H+[['拉丁 claustrum → 中世纪拉丁 claustrum → 古法语 cloistre','围合空间 → 修道院封闭区域'],['中古英语 cloistre → 英语 cloister','修道院、庭院回廊；动词又表示隔绝独处']],'建筑里的 cloister 常是围绕庭院、带顶的通道。cloister oneself 则是把自己与外界隔开，不要求真的住进修道院。','the monastery cloisters；walk through a cloister；cloister oneself away。','corridor 是一般走廊；cloister 有围合庭院、修道院等特定建筑与文化背景。',('We walked through the cloister beside the monastery garden.','我们走过修道院花园旁的回廊。'),('She cloistered herself away for a week to finish the translation.','她闭门独处了一周，以完成翻译。'),sources=['https://www.etymonline.com/word/cloister','https://en.wiktionary.org/wiki/cloister#English']),
E('closely','英 /ˈkləʊsli/；美 /ˈkloʊsli/','紧密地；仔细地；密切地；相近地','把距离缩小，也把注意力拉近，细节就更难漏掉。','close 形容词或副词 + -ly；尾部接 /sli/，不是动词 close 的 /z/。',CL[:2]+[['中古英语 close + -ly → closely','紧挨、密切、仔细地'],['现代英语 closely','关系紧密；仔细观察；相似程度高']],'watch closely 是仔细观察；closely related 是关系密切。物理位置直接说 stand close to me 更自然，不能凡是“近”就机械加 -ly。','look closely at；closely related；work closely with；closely resemble。','close 常说距离近，如 come close；closely 常强调细致、密切或紧密的方式。',('Look closely at the pattern around the edge.','仔细看看边缘周围的图案。'),('The designers worked closely with the engineers.','设计师与工程师密切合作。'),sources=['https://www.etymonline.com/word/closely','https://en.wiktionary.org/wiki/closely#English'])
]
EXCLUDE={w:'拉丁 occultus / occulere 接“隐藏”的 celare / kel- 分支，不是 claudere“关闭”；不能凭近形并为同源。' for w in ['occult','occultist','occultism','occultation']}
m=json.loads((BASE/'.cache/batch200/rewrite_spec.json').read_text());family=next(r['family'] for r in m['roots'] if r['id']=='C0232');owned=set(m['owned_words'])
R=[dict(id='C0232',meaning='关上；围住；封闭；结束',core='把开口合上，在里面与外面之间划出边界',image='把一扇门关上：include 让成员留在里面，exclude 把成员留在外面；把讨论合上，便有 conclude 和 conclusion。',intro='拉丁 claudere 表示关上、围住，分词是 clausus。在复合词里常出现 -cludere / -clusus，所以 include 与 inclusion 是同一条拉丁支线。经过法语的词外形变化更大，形成 close、enclose、closet、cloister；这些借词不能全按现代英语拼积木。',forms='claud-/claus- 是基本动词、分词的形态；复合词常用 clud-/clus-。claustr- 接 claustrum“封闭处”。close 的 /z/ 与 /s/ 要随词性和词义读，clause 的元音则是 /ɔː/。',branches=[['关闭、接近与围合空间','close、closed、closely、closure、closet、cloister、clause'],['纳入与包在里面','include、inclusion、inclusive、enclose、enclosure'],['排除与预先挡住','exclude、exclusion、exclusive、exclusively、exclusivity、preclude'],['结束与定论','conclude、conclusion、conclusive、inconclusive'],['隐居、幽闭及堵塞','recluse、reclusive、seclude、secluded、seclusion、claustrophobia、claustrophobic、occlude、occlusion'],['打开封闭的信息','disclose、disclosure']],contrasts='include 是纳入，enclose 更像围住或装进去；conclusion 是结论，conclusive 是足以定论的。inconclusive 的 in- 是否定。occult 等接“隐藏”的另一来源，不和 occlude 混为同源；recluse 的晚期拉丁词义也不能直接拿古典拉丁“打开”义替代。',practice='对同一项活动写四句话：费用 include 什么、exclude 什么、面向哪些人是 inclusive、给谁 exclusive access。再比较 close、closed、clause 的读音与意义。',words=[w for w in family if w not in EXCLUDE],exclude=EXCLUDE,sources=['https://www.etymonline.com/word/close','https://www.etymonline.com/word/recluse','https://www.etymonline.com/word/occult'])]
assert {w['word'] for w in W}==(set(family)&owned)-set(EXCLUDE)
for w in W:
 assert len(w['examples'])>=2 and len(w['history'])>=2 and w['ipa']
 assert all(len(n)==2 and all(isinstance(v,str) and v for v in n) for n in w['history'])
for k,d in [('roots',R),('words',W)]: (OUT/f'{k}_batch200_spec_21_claud.json').write_text(json.dumps(d,ensure_ascii=False,indent=2))
print('C0232',len(W),'new',len(R[0]['words']),'references',sum(len(w['examples']) for w in W),'examples','excluded',len(EXCLUDE))
